import type { Metadata } from "next";
import { authors, getAuthor, getCategory, siteConfig } from "./site";
import type { Doc, DocSummary } from "./types";
import { absoluteUrl, isoDate } from "./utils";

/* -------------------------------------------------------------------------- */
/*  Metadata helpers                                                          */
/* -------------------------------------------------------------------------- */

export const defaultOgImage = "/og";

/** Per-article social card generated by /og. */
export function ogImageFor(title: string, category?: string, kind?: "post" | "story") {
  const params = new URLSearchParams({ title });
  if (category) params.set("kicker", category);
  if (kind === "story") params.set("kind", "story");
  return `/og?${params.toString()}`;
}

export function buildMetadata({
  title,
  description,
  path,
  type = "website",
  publishedTime,
  modifiedTime,
  keywords,
  noIndex = false,
  image,
}: {
  title: string;
  description: string;
  path: string;
  type?: "website" | "article";
  publishedTime?: string;
  modifiedTime?: string;
  keywords?: string[];
  noIndex?: boolean;
  image?: string;
}): Metadata {
  const url = absoluteUrl(path);
  const ogImage = image ?? ogImageFor(title);

  return {
    title,
    description,
    keywords,
    alternates: { canonical: url },
    robots: noIndex
      ? { index: false, follow: false }
      : {
          index: true,
          follow: true,
          googleBot: {
            index: true,
            follow: true,
            "max-image-preview": "large",
            "max-snippet": -1,
            "max-video-preview": -1,
          },
        },
    openGraph: {
      type,
      url,
      title,
      description,
      siteName: siteConfig.name,
      locale: siteConfig.locale,
      ...(publishedTime ? { publishedTime } : {}),
      ...(modifiedTime ? { modifiedTime } : {}),
      images: [{ url: ogImage, width: 1200, height: 630, alt: title }],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      site: siteConfig.twitter,
      images: [ogImage],
    },
  };
}

/* -------------------------------------------------------------------------- */
/*  JSON-LD builders                                                          */
/* -------------------------------------------------------------------------- */

const publisherRef = { "@id": `${siteConfig.url}/#publisher` };
const websiteRef = { "@id": `${siteConfig.url}/#website` };

export function organizationSchema() {
  return {
    "@type": "Organization",
    "@id": `${siteConfig.url}/#publisher`,
    name: siteConfig.publisher,
    url: siteConfig.url,
    logo: {
      "@type": "ImageObject",
      url: absoluteUrl("/icon.svg"),
      width: 512,
      height: 512,
    },
    sameAs: [
      `https://x.com/${siteConfig.twitter.replace("@", "")}`,
      `https://pinterest.com/${siteConfig.pinterest}`,
    ],
  };
}

export function websiteSchema() {
  return {
    "@type": "WebSite",
    "@id": `${siteConfig.url}/#website`,
    url: siteConfig.url,
    name: siteConfig.name,
    description: siteConfig.description,
    publisher: publisherRef,
    inLanguage: "en",
    potentialAction: {
      "@type": "SearchAction",
      target: {
        "@type": "EntryPoint",
        urlTemplate: `${siteConfig.url}/search?q={search_term_string}`,
      },
      "query-input": "required name=search_term_string",
    },
  };
}

export function personSchema(slug: string) {
  const author = getAuthor(slug);
  return {
    "@type": "Person",
    "@id": `${siteConfig.url}/authors/${author.slug}#person`,
    name: author.name,
    jobTitle: author.role,
    description: author.bio,
    url: absoluteUrl(`/authors/${author.slug}`),
    worksFor: publisherRef,
  };
}

export function articleSchema(doc: Doc | DocSummary) {
  const category = getCategory(doc.category);
  const path = doc.kind === "story" ? `/stories/${doc.slug}` : `/blog/${doc.slug}`;
  const url = absoluteUrl(path);

  return {
    "@type": doc.kind === "story" ? "ShortStory" : "Article",
    "@id": `${url}#article`,
    isAccessibleForFree: true,
    headline: doc.title,
    description: doc.description,
    inLanguage: "en",
    datePublished: isoDate(doc.date),
    dateModified: isoDate(doc.updated ?? doc.date),
    wordCount: doc.wordCount,
    timeRequired: `PT${doc.readingTime}M`,
    keywords: [...doc.keywords, ...doc.tags].join(", "),
    articleSection: category?.name ?? doc.category,
    author: personSchema(doc.author),
    publisher: publisherRef,
    mainEntityOfPage: { "@type": "WebPage", "@id": url },
    image: {
      "@type": "ImageObject",
      url: absoluteUrl(doc.image ?? ogImageFor(doc.title, getCategory(doc.category)?.shortName, doc.kind)),
      width: 1200,
      height: 630,
    },
    ...(doc.kind === "story"
      ? {
          genre: "Short fiction",
          about: { "@type": "Thing", name: doc.tags[0] ?? "Fiction" },
        }
      : {}),
  };
}

export function breadcrumbSchema(items: Array<{ name: string; path: string }>) {
  return {
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

export function faqSchema(items: Array<{ question: string; answer: string }>) {
  if (items.length === 0) return null;
  return {
    "@type": "FAQPage",
    mainEntity: items.map((item) => ({
      "@type": "Question",
      name: item.question,
      acceptedAnswer: { "@type": "Answer", text: item.answer },
    })),
  };
}

export function itemListSchema(docs: DocSummary[], name: string, path: string) {
  return {
    "@type": "ItemList",
    name,
    url: absoluteUrl(path),
    numberOfItems: docs.length,
    itemListElement: docs.map((doc, index) => ({
      "@type": "ListItem",
      position: index + 1,
      url: absoluteUrl(doc.kind === "story" ? `/stories/${doc.slug}` : `/blog/${doc.slug}`),
      name: doc.title,
    })),
  };
}

export function graph(nodes: Array<Record<string, unknown> | null>) {
  return {
    "@context": "https://schema.org",
    "@graph": [
      organizationSchema(),
      websiteSchema(),
      ...authors.map((author) => personSchema(author.slug)),
      ...nodes.filter((node): node is Record<string, unknown> => node !== null),
    ],
  };
}
